// TestPostCommit_IdleSessionEmptyFilesTouched_NotCondensed verifies that an IDLE
// session with hasNew=true but empty FilesTouched is NOT condensed into a commit.
//
// This can happen for conversation-only sessions where the transcript grew but no
// files were modified. Previously, filesOverlapWithContent was called with an empty
// list and returned false. The shouldCondenseWithOverlapCheck method must also
// return false when filesTouchedBefore is empty.
func TestPostCommit_IdleSessionEmptyFilesTouched_NotCondensed(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	// --- Create an IDLE session with a checkpoint but no files touched ---
	idleSessionID := "idle-no-files-session"
	setupSessionWithCheckpoint(t, s, repo, dir, idleSessionID)

	idleState, err := s.loadSessionState(context.Background(), idleSessionID)
	require.NoError(t, err)
	idleState.Phase = session.PhaseIdle
	// Clear FilesTouched to simulate a conversation-only session
	idleState.FilesTouched = nil
	// CheckpointTranscriptStart=0 so sessionHasNewContent returns true
	idleState.CheckpointTranscriptStart = 0
	require.NoError(t, s.saveSessionState(context.Background(), idleState))

	idleOriginalStepCount := idleState.StepCount

	// --- Make a commit with an unrelated file ---
	wt, err := repo.Worktree()
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(dir, "other-work.txt"), []byte("other work"), 0o644))
	_, err = wt.Add("other-work.txt")
	require.NoError(t, err)

	cpID := "f1f2f3f4f5f6"
	commitMsg := "other work\n\n" + trailers.CheckpointTrailerKey + ": " + cpID + "\n"
	_, err = wt.Commit(commitMsg, &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// --- Verify: IDLE session with no files was NOT condensed ---
	idleState, err = s.loadSessionState(context.Background(), idleSessionID)
	require.NoError(t, err)

	assert.Equal(t, idleOriginalStepCount, idleState.StepCount,
		"IDLE session with empty FilesTouched should NOT be condensed")
	assert.Equal(t, session.PhaseIdle, idleState.Phase,
		"IDLE session should remain IDLE")
	// BaseCommit is NOT updated for non-ACTIVE sessions (updateBaseCommitIfChanged skips them)
}

// TestPostCommit_IdleSession_NoTranscriptFallbackForCarryForward verifies that
// carry-forward computation for IDLE sessions does NOT fall back to transcript
// extraction. Only ACTIVE sessions (mid-session commits before Stop) should parse
// the transcript, because IDLE sessions have FilesTouched populated by SaveStep.
//
// Regression test: resolveFilesTouched unconditionally falls back to transcript
// extraction, but the PostCommit call site must gate it on IsActive().
func TestPostCommit_IdleSession_NoTranscriptFallbackForCarryForward(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	// Create an IDLE session with checkpoint
	sessionID := "idle-transcript-guard"
	setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

	state, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseIdle
	// Clear FilesTouched to simulate the edge case
	state.FilesTouched = nil
	// Set transcript info so transcript extraction WOULD find files if called
	state.AgentType = agent.AgentTypeGemini
	transcriptPath := filepath.Join(dir, "idle-transcript.json")
	transcript := `{
  "messages": [
    {"type": "user", "content": [{"text": "create file"}]},
    {"type": "gemini", "content": "", "toolCalls": [{"name": "write_file", "args": {"file_path": "` + filepath.Join(dir, "test.txt") + `"}}]}
  ]
}`
	require.NoError(t, os.WriteFile(transcriptPath, []byte(transcript), 0o644))
	state.TranscriptPath = transcriptPath
	state.CheckpointTranscriptStart = 0
	require.NoError(t, s.saveSessionState(context.Background(), state))

	originalStepCount := state.StepCount

	// Commit the file the transcript references — if transcript extraction
	// ran, it would find overlap and trigger condensation
	wt, err := repo.Worktree()
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(dir, "test.txt"), []byte("committed"), 0o644))
	_, err = wt.Add("test.txt")
	require.NoError(t, err)

	cpID := "a1a2a3a4a5a6"
	commitMsg := "commit test.txt\n\n" + trailers.CheckpointTrailerKey + ": " + cpID + "\n"
	_, err = wt.Commit(commitMsg, &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify: IDLE session was NOT condensed (transcript fallback was skipped)
	state, err = s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	assert.Equal(t, originalStepCount, state.StepCount,
		"IDLE session should NOT be condensed via transcript fallback — only ACTIVE sessions get transcript extraction for carry-forward")
}

// TestPostCommit_NonActiveSession_SkipsSentinelWait is a regression test verifying
// that PostCommit for an IDLE or ENDED session with AgentType=ClaudeCode and a
// TranscriptPath completes quickly without hitting the 3s sentinel timeout in
// PrepareTranscript. Both IDLE and ENDED sessions should skip the sentinel wait
// since their transcripts are already fully flushed.
//
// Before the fix, the transcript extraction functions called PrepareTranscript
// unconditionally, which triggered waitForTranscriptFlush (3s timeout) even for
// idle/ended sessions where the transcript was already fully flushed.
//
// After the fix, PrepareTranscript is only called when state.Phase.IsActive().
func TestPostCommit_NonActiveSession_SkipsSentinelWait(t *testing.T) {
	tests := []struct {
		name         string
		phase        session.Phase
		setEndedAt   bool
		sessionID    string
		commitTrlSHA string
	}{
		{"idle", session.PhaseIdle, false, "test-idle-skip-sentinel", "a1a2a3a4a5a6"},
		{"ended", session.PhaseEnded, true, "test-ended-skip-sentinel", "e1e2e3e4e5e6"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir := setupGitRepo(t)
			t.Chdir(dir)

			repo, err := git.PlainOpen(dir)
			require.NoError(t, err)

			s := &ManualCommitStrategy{}

			// Initialize session and save a checkpoint
			setupSessionWithCheckpoint(t, s, repo, dir, tt.sessionID)

			// Set phase, AgentType=ClaudeCode, and TranscriptPath. Without
			// TranscriptPath the PrepareTranscript code path is never reached;
			// without AgentType=ClaudeCode the sentinel wait is not triggered.
			state, err := s.loadSessionState(context.Background(), tt.sessionID)
			require.NoError(t, err)
			state.Phase = tt.phase
			if tt.setEndedAt {
				now := time.Now()
				state.EndedAt = &now
			} else {
				state.LastInteractionTime = nil
			}
			state.FilesTouched = []string{"test.txt"}
			state.AgentType = agent.AgentTypeClaudeCode

			// Create a transcript file so PrepareTranscript would be triggered if not guarded
			transcriptFile := filepath.Join(dir, ".entire", "transcript-"+tt.sessionID+".jsonl")
			require.NoError(t, os.MkdirAll(filepath.Dir(transcriptFile), 0o755))
			require.NoError(t, os.WriteFile(transcriptFile, []byte(`{"type":"human"}`+"\n"), 0o644))
			state.TranscriptPath = transcriptFile

			require.NoError(t, s.saveSessionState(context.Background(), state))

			// Create a commit WITH the Entire-Checkpoint trailer
			commitWithCheckpointTrailer(t, repo, dir, tt.commitTrlSHA)

			// Time PostCommit — before the fix this would take ~3s+ due to sentinel timeout.

		findSessionsSpan.End()
		return nil
	}

	// Find all active sessions for this worktree
	// We match by worktree (not BaseCommit) because the user may have made
	// intermediate commits without entering new prompts, causing HEAD to diverge
	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		// No active sessions or error listing - silently skip (hooks must be resilient)
		logging.Debug(logCtx, "prepare-commit-msg: no active sessions",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}
	findSessionsSpan.End()

	s.warnIfAttributionDiverged(ctx, sessions)

	// Fast path: skip content detection for mid-turn agent commits.
	if s.tryAgentCommitFastPath(ctx, commitMsgFile, sessions, source) {
		return nil
	}

	// Check if any session has new content to condense
	_, filterSessionsSpan := perf.Start(ctx, "filter_sessions_with_content")
	sessionsWithContent := s.filterSessionsWithNewContent(ctx, repo, sessions)
	filterSessionsSpan.End()

	if len(sessionsWithContent) == 0 {
		// No new content — no trailer needed
		logging.Debug(logCtx, "prepare-commit-msg: no content to link",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.Int("sessions_found", len(sessions)),
		)
		return nil
	}

	// Read current commit message
	_, readCommitMessageSpan := perf.Start(ctx, "read_commit_message")
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		readCommitMessageSpan.RecordError(err)
		readCommitMessageSpan.End()
		return nil
	}

	message := string(content)

	// Check if trailer already exists (ParseCheckpoint validates format, so found==true means valid)
	if existingCpID, found := trailers.ParseCheckpoint(message); found {
		readCommitMessageSpan.End()
		// Trailer already exists (e.g., amend) - keep it
		logging.Debug(logCtx, "prepare-commit-msg: trailer already exists",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.String("existing_checkpoint_id", existingCpID.String()),
		)
		return nil
	}
	readCommitMessageSpan.End()

	// Generate a fresh checkpoint ID and resolve session metadata
	_, resolveMetadataSpan := perf.Start(ctx, "resolve_session_metadata")
	checkpointID, err := checkpoint.GenerateCheckpointID(ctx)
	if err != nil {
		resolveMetadataSpan.RecordError(err)
		resolveMetadataSpan.End()
		return fmt.Errorf("failed to generate checkpoint ID: %w", err)
	}

	// Determine agent type and last prompt from session
	var agentType types.AgentType
	var lastPrompt string
	if len(sessionsWithContent) > 0 {
		firstSession := sessionsWithContent[0]
		if firstSession.AgentType != "" {
			agentType = firstSession.AgentType
		}
		lastPrompt = s.getLastPrompt(ctx, repo, firstSession)
	}

	// Prepare prompt for display: collapse newlines/whitespace, then truncate (rune-safe)
	displayPrompt := stringutil.TruncateRunes(stringutil.CollapseWhitespace(lastPrompt), 80, "...")

	// Load commit_linking setting to decide whether to prompt
	commitLinking := settings.CommitLinkingPrompt // safe default
	if stngs, loadErr := settings.Load(ctx); loadErr == nil {
		commitLinking = stngs.GetCommitLinking()
	}
	resolveMetadataSpan.End()

	// Add trailer differently based on commit source
	// NOTE: TTY confirmation (askConfirmTTY) is intentionally NOT wrapped in a span
	// because it blocks on user input and would skew timing.
	switch source {
	case "message":
		// Using -m or -F: behavior depends on TTY availability and commit_linking setting
		switch {
		case !interactive.CanPromptInteractively():
			// No TTY (agent subprocess, CI) — auto-link without prompting
			message = addCheckpointTrailer(message, checkpointID)
		case commitLinking == settings.CommitLinkingAlways:
			// User previously chose "always" — auto-link without prompting
			message = addCheckpointTrailer(message, checkpointID)
		default:
			// Human at terminal — prompt interactively
			header := "Entire: Active " + string(agentType) + " session detected"
			var details []string
			if displayPrompt != "" {
				details = append(details, "Last prompt: "+displayPrompt)
			}

			result := askConfirmTTY(header, details, "Link this commit to session context?", true)
			if result == ttyResultSkip {
				logging.Debug(logCtx, "prepare-commit-msg: user declined trailer",
					slog.String("strategy", "manual-commit"),
					slog.String("source", source),
				)
				return nil
			}
			if result == ttyResultLinkAlways {
				// Persist preference so future commits auto-link (non-fatal if it fails)
				if saveErr := saveCommitLinkingAlways(ctx); saveErr != nil {
					logging.Warn(logCtx, "prepare-commit-msg: failed to save commit_linking=always",
						slog.String("error", saveErr.Error()),
					)
				}
			}
			message = addCheckpointTrailer(message, checkpointID)
		}
	default:
		// Normal editor flow: add trailer with explanatory comment (will be stripped by git)
		message = addCheckpointTrailerWithComment(message, checkpointID, string(agentType), displayPrompt)
	}

	logging.Info(logCtx, "prepare-commit-msg: trailer added",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.String("checkpoint_id", checkpointID.String()),
	)

	// Write updated message back
	_, writeCommitMessageSpan := perf.Start(ctx, "write_commit_message")
	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
		writeCommitMessageSpan.RecordError(err)
		writeCommitMessageSpan.End()
		return nil
	}
	writeCommitMessageSpan.End()

	return nil
}

// handleAmendCommitMsg handles the prepare-commit-msg hook for amend operations
// (source="commit"). It preserves existing trailers or restores from LastCheckpointID.
func (s *ManualCommitStrategy) handleAmendCommitMsg(ctx context.Context, commitMsgFile string) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	// Read current commit message
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return nil
	}

	message := string(content)

	// If message already has a trailer, keep it unchanged
	if existingCpID, found := trailers.ParseCheckpoint(message); found {
		logging.Debug(logCtx, "prepare-commit-msg: amend preserves existing trailer",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", existingCpID.String()),
		)
		return nil
	}

	// No trailer in message — check if any session has LastCheckpointID to restore
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil
	}

	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		return nil
	}

	// For amend, HEAD^ is the commit being amended, and HEAD is where we are now.
	// We need to match sessions whose BaseCommit equals HEAD (the commit being amended
	// was created from this base). This prevents stale sessions from injecting
	// unrelated checkpoint IDs.
	repo, repoErr := OpenRepository(ctx)
	if repoErr != nil {
		return nil
	}
	defer repo.Close()
	head, headErr := repo.Head()
	if headErr != nil {
		return nil
	}
	currentHead := head.Hash().String()

	// Find first matching session with LastCheckpointID to restore.
	// LastCheckpointID is set after condensation completes.
	for _, state := range sessions {
		if state.BaseCommit != currentHead {
			continue
		}
		if state.LastCheckpointID.IsEmpty() {
			continue
		}
		cpID := state.LastCheckpointID
		source := "LastCheckpointID"

		// Restore the trailer
		message = addCheckpointTrailer(message, cpID)
		if writeErr := os.WriteFile(commitMsgFile, []byte(message), 0o600); writeErr != nil { //nolint:gosec // path from git hook arg
			return nil
		}

		logging.Info(logCtx, "prepare-commit-msg: restored trailer on amend",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", cpID.String()),
			slog.String("session_id", state.SessionID),
			slog.String("source", source),
		)
		return nil
	}

	// No checkpoint ID found - leave message unchanged
	logging.Debug(logCtx, "prepare-commit-msg: amend with no checkpoint to restore",
		slog.String("strategy", "manual-commit"),
	)
	return nil
}

